struct Node {
    int data;
    Node* next;
};

// Function to reverse a singly linked list in place
void reverseList(Node** head) {
    Node* prev = NULL;
    Node* current = *head;
    Node* next = NULL;

    while (current != NULL) {
        // Store the next node before updating current->next
        next = current->next;

        // Update current->next to point to prev
        current->next = prev;

        // Move prev and current one step forward
        prev = current;
        current = next;
    }

    // Update the head pointer to point to the new head (which is the last node)
    *head = prev;
}
```

Example usage:

